import math


class DataStatistics4:

    TOLERANCE = 1e-15

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        mean1 = DataStatistics4._mean(data1)
        mean2 = DataStatistics4._mean(data2)

        numerator = DataStatistics4._covariance_sum(data1, data2, mean1, mean2, n)
        denominator = DataStatistics4._correlation_denominator(data1, data2, mean1, mean2, n)

        return numerator / denominator if denominator > DataStatistics4.TOLERANCE else 0

    @staticmethod
    def _mean(data):
        n = len(data)
        return sum(data) / n

    @staticmethod
    def _covariance_sum(data1, data2, mean1, mean2, n):
        return sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))

    @staticmethod
    def _correlation_denominator(data1, data2, mean1, mean2, n):
        variance1 = sum((data1[i] - mean1) ** 2 for i in range(n))
        variance2 = sum((data2[i] - mean2) ** 2 for i in range(n))
        return math.sqrt(variance1) * math.sqrt(variance2)

    @staticmethod
    def skewness(data):
        n = len(data)
        mean = DataStatistics4._mean(data)
        std_deviation = DataStatistics4._std_dev(data, mean, n)

        if std_deviation <= DataStatistics4.TOLERANCE:
            return 0

        return DataStatistics4._skewness_numerator(data, mean, n) / ((n - 1) * (n - 2) * std_deviation ** 3)

    @staticmethod
    def _std_dev(data, mean=None, n=None):
        if mean is None:
            mean = DataStatistics4._mean(data)
        if n is None:
            n = len(data)
        variance = sum((x - mean) ** 2 for x in data) / n
        return math.sqrt(variance)

    @staticmethod
    def _skewness_numerator(data, mean, n):
        return sum((x - mean) ** 3 for x in data) * n

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mean = DataStatistics4._mean(data)
        std_dev = DataStatistics4._std_dev(data, mean, n)

        if std_dev <= DataStatistics4.TOLERANCE:
            return math.nan

        kurtosis_value = DataStatistics4._excess_kurtosis(data, mean, std_dev, n)
        return kurtosis_value

    @staticmethod
    def _excess_kurtosis(data, mean, std_dev, n):
        centered_data = [x - mean for x in data]
        fourth_moment = sum(x ** 4 for x in centered_data) / n
        return (fourth_moment / std_dev ** 4) - 3

    @staticmethod
    def pdf(data, mu, sigma):
        pdf_values = [
            1 / (sigma * math.sqrt(2 * math.pi)) * math.exp(-0.5 * ((x - mu) / sigma) ** 2)
            for x in data
        ]
        return pdf_values
